import React from "react";

export default function Footer() {
  return (
    <footer className="modern-footer">
      <div className="footer-container">
        <div className="footer-content">
          {/* Section Veille Marchés */}
          <div className="footer-column">
            <h3 className="footer-title">Veille Marchés</h3>
            <p className="footer-description">
              La solution intelligente pour votre veille des marchés publics
            </p>
          </div>

          {/* Section Navigation */}
          <div className="footer-column">
            <h3 className="footer-title">Navigation</h3>
            <ul className="footer-links">
              <li>
                <a href="#accueil">Accueil</a>
              </li>
              <li>
                <a href="#fonctionnalites">Fonctionnalités</a>
              </li>
              <li>
                <a href="#tarifs">Tarifs</a>
              </li>
              <li>
                <a href="#contact">Contact</a>
              </li>
            </ul>
          </div>

          {/* Section Ressources */}
          <div className="footer-column">
            <h3 className="footer-title">Ressources</h3>
            <ul className="footer-links">
              <li>
                <a href="#faq">FAQ</a>
              </li>
              <li>
                <a href="#aide">Centre d'aide</a>
              </li>
              <li>
                <a href="#mentions">Mentions légales</a>
              </li>
              <li>
                <a href="#confidentialite">Politique de confidentialité</a>
              </li>
            </ul>
          </div>

          {/* Section Contact */}
          <div className="footer-column">
            <h3 className="footer-title">Contact</h3>
            <div className="contact-info">
              <p className="contact-item">
                <span className="contact-icon">✉</span>
                contact@veillemarches.fr
              </p>
              <p className="contact-item">
                <span className="contact-icon">📞</span>
                +226 65297163
              </p>
              <div className="social-links">
                <a href="#linkedin" className="social-link">
                  <svg
                    width="20"
                    height="20"
                    viewBox="0 0 24 24"
                    fill="currentColor"
                  >
                    <path d="M20.447 20.452h-3.554v-5.569c0-1.328-.027-3.037-1.852-3.037-1.853 0-2.136 1.445-2.136 2.939v5.667H9.351V9h3.414v1.561h.046c.477-.9 1.637-1.85 3.37-1.85 3.601 0 4.267 2.37 4.267 5.455v6.286zM5.337 7.433c-1.144 0-2.063-.926-2.063-2.065 0-1.138.92-2.063 2.063-2.063 1.14 0 2.064.925 2.064 2.063 0 1.139-.925 2.065-2.064 2.065zm1.782 13.019H3.555V9h3.564v11.452zM22.225 0H1.771C.792 0 0 .774 0 1.729v20.542C0 23.227.792 24 1.771 24h20.451C23.2 24 24 23.227 24 22.271V1.729C24 .774 23.2 0 22.222 0h.003z" />
                  </svg>
                  LinkedIn
                </a>
                <a href="#twitter" className="social-link">
                  <svg
                    width="20"
                    height="20"
                    viewBox="0 0 24 24"
                    fill="currentColor"
                  >
                    <path d="M18.244 2.25h3.308l-7.227 8.26 8.502 11.24H16.17l-5.214-6.817L4.99 21.75H1.68l7.73-8.835L1.254 2.25H8.08l4.713 6.231zm-1.161 17.52h1.833L7.084 4.126H5.117z" />
                  </svg>
                  X
                </a>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* Copyright */}
      <div className="footer-bottom">
        <div className="footer-container">
          <p className="copyright">
            © 2025 Veille Marchés. Tous droits réservés.
          </p>
        </div>
      </div>

      <style jsx>{`
        .modern-footer {
          background: linear-gradient(135deg, #003865 0%, #002347 100%);
          color: white;
          padding: 60px 0 0;
          margin-top: 80px;
        }

        .footer-container {
          max-width: 1200px;
          margin: 0 auto;
          padding: 0 20px;
        }

        .footer-content {
          display: grid;
          grid-template-columns: 2fr 1fr 1fr 1.5fr;
          gap: 40px;
          margin-bottom: 40px;
        }

        .footer-column {
          display: flex;
          flex-direction: column;
        }

        .footer-title {
          color: white;
          font-size: 1.25rem;
          font-weight: 700;
          margin-bottom: 20px;
          position: relative;
        }

        .footer-title::after {
          content: "";
          position: absolute;
          bottom: -8px;
          left: 0;
          width: 40px;
          height: 3px;
          background: linear-gradient(90deg, #ef5b0c, #ff7b3d);
          border-radius: 2px;
        }

        .footer-description {
          color: rgba(255, 255, 255, 0.8);
          line-height: 1.6;
          font-size: 0.95rem;
        }

        .footer-links {
          list-style: none;
          padding: 0;
          margin: 0;
        }

        .footer-links li {
          margin-bottom: 12px;
        }

        .footer-links a {
          color: rgba(255, 255, 255, 0.8);
          text-decoration: none;
          font-size: 0.95rem;
          transition: color 0.3s ease;
        }

        .footer-links a:hover {
          color: #ef5b0c;
        }

        .contact-info {
          display: flex;
          flex-direction: column;
          gap: 15px;
        }

        .contact-item {
          display: flex;
          align-items: center;
          color: rgba(255, 255, 255, 0.8);
          font-size: 0.95rem;
          margin: 0;
        }

        .contact-icon {
          margin-right: 12px;
          font-size: 1.1rem;
        }

        .social-links {
          display: flex;
          gap: 15px;
          margin-top: 10px;
        }

        .social-link {
          display: flex;
          align-items: center;
          gap: 8px;
          color: rgba(255, 255, 255, 0.8);
          text-decoration: none;
          font-size: 0.9rem;
          transition: all 0.3s ease;
          padding: 8px 12px;
          border-radius: 8px;
          background: rgba(255, 255, 255, 0.1);
        }

        .social-link:hover {
          color: #ef5b0c;
          background: rgba(239, 91, 12, 0.1);
          transform: translateY(-2px);
        }

        .footer-bottom {
          border-top: 1px solid rgba(255, 255, 255, 0.1);
          padding: 25px 0;
          background: rgba(0, 0, 0, 0.2);
        }

        .copyright {
          text-align: center;
          color: rgba(255, 255, 255, 0.6);
          font-size: 0.9rem;
          margin: 0;
        }

        /* Responsive Design */
        @media (max-width: 768px) {
          .modern-footer {
            padding: 40px 0 0;
          }

          .footer-content {
            grid-template-columns: 1fr;
            gap: 30px;
            text-align: center;
          }

          .footer-title::after {
            left: 50%;
            transform: translateX(-50%);
          }

          .social-links {
            justify-content: center;
          }

          .contact-item {
            justify-content: center;
          }
        }

        @media (max-width: 992px) and (min-width: 769px) {
          .footer-content {
            grid-template-columns: 1fr 1fr;
            gap: 35px;
          }
        }
      `}</style>
    </footer>
  );
}
